INSERT INTO public.agency_projects (slug,title,discipline,category,image,alt,description,brief,approach,deliverables,is_concept,published,sort_order) VALUES
('beyond-the-road','Beyond the road','AUTOMOTIVE / WORLD BUILDING','Hybrid','/images/beyond-the-road.webp','Black sports car in a red desert canyon beneath a floating silver monolith','Real-world detail. An otherworldly destination.','Explore an automotive campaign that pairs the precision of a product shoot with an environment that could only exist in the imagination.','The proposed production would capture the car, reflections and movement on set, then extend the environment with generative imagery and carefully matched compositing. This visual is an AI-generated study of that direction.',ARRAY['Campaign key visual','Environment exploration','Social & out-of-home layouts']::text[],true,true,1),
('a-different-current','A different current','FASHION / EDITORIAL','Film & photo','/images/a-different-current.webp','Fashion concept of a woman in an orange dress on a rugged Mediterranean coast','The elements become part of the story.','Develop a fashion story around movement, texture and the tension between soft fabric and a wild coastal landscape.','A photographic treatment for a location-led shoot. Casting, natural light, choreography and styling would carry the final campaign. This AI-generated mood study illustrates the intended art direction; it is not a completed live shoot.',ARRAY['Photographic art direction','Location & styling treatment','Campaign format studies']::text[],true,true,2),
('a-new-nature','A new nature','BEAUTY / SYNTHETIC STILL LIFE','Generative AI','/images/a-new-nature.webp','Chartreuse perfume bottle on dark wet rock in a sculptural studio world','A small object. A world of possibilities.','Imagine a distinctive beauty campaign where fragrance is expressed through light, material and impossible arrangements.','An original generative still-life concept, shaped through art direction, image generation and finishing. For a commissioned product, packaging details and product claims would be checked against approved reference assets.',ARRAY['Product concept imagery','Material & light studies','Campaign adaptation direction']::text[],true,true,3)
